        Assert.Null(await Detect(SampleFiles.Docx(withDocument: false)));
        Assert.Null(await Detect([0x50, 0x4B, 0x03, 0x04, 1, 2, 3, 4, 5]));   // zip header, no zip
        Assert.Null(await Detect([]));
    }

